export default function handler(req: VercelRequest, res: VercelResponse) {
  if (req.method !== 'GET') return res.status(405).json({ error: 'Method Not Allowed' });

  const { grado, asignatura } = req.query;
  if (!grado || !asignatura) {
    return res.status(400).json({ error: 'Faltan parámetros: grado y asignatura' });
  }

  const filtrados = OAS.filter(
    (oa) => oa.grado === String(grado) && oa.asignatura === String(asignatura)
  );

  res.setHeader('Cache-Control', 's-maxage=3600');
  return res.status(200).json({ oas: filtrados });
}
